<?php require_once "../db.php";require_role("Teacher");$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){$title=trim($_POST["title"]);$subject=trim($_POST["subject"]);$desc=trim($_POST["description"]);$duration=(int)$_POST["duration"];$uid=current_id();$st=$conn->prepare("INSERT INTO quiz(title,subject,description,duration,created_by) VALUES(?,?,?,?,?)");$st->bind_param("sssii",$title,$subject,$desc,$duration,$uid);if($st->execute())go("manage_quiz.php");else$err=$conn->error;}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Quiz</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/teacher_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><div class="card panel-card col-xl-8"><div class="card-body p-4"><h2 class="fw-bold">Create New Quiz</h2><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post"><label class="form-label">Quiz Title</label><input name="title" class="form-control mb-3" required><label class="form-label">Subject</label><input name="subject" class="form-control mb-3"><label class="form-label">Description</label><textarea name="description" class="form-control mb-3" rows="4"></textarea><label class="form-label">Duration (minutes)</label><input type="number" name="duration" value="30" min="1" class="form-control mb-3"><button class="btn btn-primary">Create Quiz</button></form></div></div></div></main></div></div></body></html>
